import pandas as pd

def run(inputs: dict) -> dict:
    df = inputs["payments"].copy()

    valid_currencies = {"USD", "EUR", "GBP"}

    def classify(row):
        amount = row["amount"]
        currency = row["currency"]
        country = row["country"]

        if pd.isna(amount):
            return "AMT_NULL"
        if amount <= 0:
            return "AMT_NONPOS"
        if pd.isna(currency) or currency not in valid_currencies:
            return "CCY_INVALID"
        if pd.isna(country):
            return "CTRY_NULL"
        return None

    reason_codes = df.apply(classify, axis=1)

    rejected_mask = reason_codes.notna()

    payments_clean = df.loc[~rejected_mask].copy()
    payments_clean["amount"] = payments_clean["amount"].round(2)
    payments_clean = payments_clean.reset_index(drop=True)

    payments_rejects = df.loc[rejected_mask].copy()
    payments_rejects["reason_code"] = reason_codes.loc[rejected_mask]
    payments_rejects = payments_rejects.reset_index(drop=True)

    return {
        "payments_clean": payments_clean,
        "payments_rejects": payments_rejects,
    }
